    #[test]
    fn stale_network_prunable_removes_owned_and_unlabeled_endpointless() {
        // This daemon's own label (or a direct slot child) is stale at startup.
        assert!(stale_network_prunable("/daemon/work", 3, "/daemon/work"));
        assert!(stale_network_prunable(
            "/daemon/work/slot-2",
            1,
            "/daemon/work"
        ));
        // Unlabeled guest-plan leak with no endpoints is reclaimed as a backstop.
        assert!(stale_network_prunable("", 0, "/daemon/work"));
        // Unlabeled but still connected: left alone.
        assert!(!stale_network_prunable("", 2, "/daemon/work"));
        // A foreign daemon's labeled network is never touched, even endpoint-less.
        assert!(!stale_network_prunable("/other/work", 0, "/daemon/work"));
        assert!(!stale_network_prunable(
            "/other/work/slot-1",
            0,
            "/daemon/work"
        ));
    }

    #[test]
    fn stale_job_container_remove_force_deletes_running_orphans() {
        // Startup prune used to call `docker rm` without --force. Running
        // orphans (cancelled jobs, 401 completion) stayed Up, kept their
        // networks, and exhausted Docker's address pool.
        assert_eq!(
            stale_job_container_remove_args(&[
                "velnor-job-aaaa".to_owned(),
                "velnor-job-bbbb".to_owned()
            ]),
            vec![
                "rm".to_owned(),
                "--force".to_owned(),
                "velnor-job-aaaa".to_owned(),
                "velnor-job-bbbb".to_owned()
            ]
        );
    }

    #[test]
    fn reclaim_orphan_job_containers_keeps_in_flight_and_removes_stale() {
        let live = BTreeSet::from(["velnor-job-live".to_owned()]);
        let removed = reclaim_orphan_job_containers_with("/daemon/work", &live, |args| {
            if args == ["ps", "-aq", "--filter", "name=velnor-job"] {
                return Some(std::process::Output {
                    status: success_exit_status(),
                    stdout: b"id-live\nid-dead\n".to_vec(),
                    stderr: Vec::new(),
                });
            }
            if args == ["ps", "-aq", "--filter", "name=velnor-mise-seed"] {
                return Some(std::process::Output {
                    status: success_exit_status(),
                    stdout: Vec::new(),
                    stderr: Vec::new(),
                });
            }
            if args.first() == Some(&"inspect") && args.last() == Some(&"id-live") {
                return Some(std::process::Output {
                    status: success_exit_status(),
                    stdout: b"/daemon/work/slot-1\tvelnor-job-live\n".to_vec(),
                    stderr: Vec::new(),
                });
            }
            if args.first() == Some(&"inspect") && args.last() == Some(&"id-dead") {
                return Some(std::process::Output {
                    status: success_exit_status(),
                    stdout: b"/daemon/work/slot-2\tvelnor-job-dead\n".to_vec(),
                    stderr: Vec::new(),
                });
            }
            if args.first() == Some(&"rm") {
                let expected = stale_job_container_remove_args(&["id-dead".to_owned()]);
                assert_eq!(
                    args,
                    expected.iter().map(String::as_str).collect::<Vec<_>>()
                );
                return Some(std::process::Output {
                    status: success_exit_status(),
                    stdout: Vec::new(),
                    stderr: Vec::new(),
                });
            }
            None
        });
        assert_eq!(removed, 1);
    }

    #[test]
    fn reclaim_rechecks_in_flight_markers_immediately_before_rm() {
        let live = BTreeSet::new();
        let removed = reclaim_orphan_job_containers_refreshing(
            "/daemon/work",
            &live,
            || Ok(BTreeSet::from(["velnor-job-new".to_owned()])),
            |args| {
                if args == ["ps", "-aq", "--filter", "name=velnor-job"] {
                    return Some(std::process::Output {
                        status: success_exit_status(),
                        stdout: b"id-new\n".to_vec(),
                        stderr: Vec::new(),
                    });
                }
                if args == ["ps", "-aq", "--filter", "name=velnor-mise-seed"] {
                    return Some(std::process::Output {
                        status: success_exit_status(),
                        stdout: Vec::new(),
                        stderr: Vec::new(),
                    });
                }
                if args.first() == Some(&"inspect") && args.last() == Some(&"id-new") {
                    return Some(std::process::Output {
                        status: success_exit_status(),
                        stdout: b"/daemon/work/slot-2\tvelnor-job-new\n".to_vec(),
                        stderr: Vec::new(),
                    });
                }
                if args == ["network", "ls", "-q", "--filter", "name=velnor-net"] {
                    return Some(std::process::Output {
                        status: success_exit_status(),
                        stdout: Vec::new(),
                        stderr: Vec::new(),
                    });
                }
                if args.first() == Some(&"rm") {
                    panic!(
                        "a container admitted after the first snapshot must not be force-removed"
                    );
                }
                None
            },
        );
        assert_eq!(removed, 0);
    }

