    #[test]
    fn queue_time_presence_uses_explicit_and_system_fallbacks() {
        let explicit: AgentJobRequestMessage = serde_json::from_value(serde_json::json!({
            "MessageType": "PipelineAgentJobRequest",
            "Plan": { "PlanId": "plan" },
            "Timeline": { "Id": "timeline" },
            "JobId": "explicit",
            "JobDisplayName": "job",
            "RequestId": 1,
            "QueueTime": "2026-08-30T00:00:00Z"
        }))
        .unwrap();
        assert!(job_queue_time_present(&explicit));

        let fallback: AgentJobRequestMessage = serde_json::from_value(serde_json::json!({
            "MessageType": "PipelineAgentJobRequest",
            "Plan": { "PlanId": "plan" },
            "Timeline": { "Id": "timeline" },
            "JobId": "fallback",
            "JobDisplayName": "job",
            "RequestId": 1,
            "Variables": {
                "system.queueTime": { "Value": "2026-08-30T00:00:00Z" }
            }
        }))
        .unwrap();
        assert!(job_queue_time_present(&fallback));

        let empty_explicit: AgentJobRequestMessage = serde_json::from_value(serde_json::json!({
            "MessageType": "PipelineAgentJobRequest",
            "Plan": { "PlanId": "plan" },
            "Timeline": { "Id": "timeline" },
            "JobId": "empty-explicit",
            "JobDisplayName": "job",
            "RequestId": 1,
            "QueueTime": " ",
            "Variables": {
                "system.queueTime": { "Value": "2026-08-30T00:00:00Z" }
            }
        }))
        .unwrap();
        assert_eq!(
            job_queue_time(&empty_explicit),
            Some("2026-08-30T00:00:00Z")
        );

        for (raw, present) in [
            ("", false),
            ("  ", false),
            ("not-a-timestamp", true),
            ("2999-01-01T00:00:00Z", true),
        ] {
            let job: AgentJobRequestMessage = serde_json::from_value(serde_json::json!({
                "MessageType": "PipelineAgentJobRequest",
                "Plan": { "PlanId": "plan" },
                "Timeline": { "Id": "timeline" },
                "JobId": "edge",
                "JobDisplayName": "job",
                "RequestId": 1,
                "QueueTime": raw
            }))
            .unwrap();
            assert_eq!(job_queue_time_present(&job), present, "raw={raw:?}");
            assert_eq!(job_queued_for(&job, SystemTime::now()), Duration::ZERO);
        }
    }

    #[test]
    fn plan_summary_telemetry_uses_backend_count_not_synthetic_logs() {
        let job_id = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
        let first_step_id = "11111111-1111-4111-8111-111111111111";
        let second_step_id = "33333333-3333-4333-8333-333333333333";
        let job = AgentJobRequestMessage::from_value(serde_json::json!({
            "messageType": "PipelineAgentJobRequest",
            "plan": { "planId": "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb" },
            "timeline": { "id": "cccccccc-cccc-4ccc-8ccc-cccccccccccc" },
            "jobId": job_id,
            "jobDisplayName": "job",
            "requestId": 1,
            "steps": [
                { "type": 4, "id": first_step_id, "enabled": true },
                { "type": 4, "id": "22222222-2222-4222-8222-222222222222", "enabled": false },
                { "type": 4, "id": second_step_id, "enabled": true }
            ]
        }))
        .unwrap();
        let fields = plan_summary_telemetry_fields(&job, Some(1)).unwrap();

        assert_eq!(fields["logical_tasks"], Value::from(2_u64));
        assert_eq!(fields["physical_actions"], Value::from(1_u64));
        assert_eq!(fields["counts_scope"], Value::from("runner_execution"));
        let serialized_fields = serde_json::to_string(&fields).unwrap();
        assert!(!serialized_fields.contains(job_id));
        assert!(!serialized_fields.contains(first_step_id));
        assert!(!serialized_fields.contains(second_step_id));
        assert_eq!(fields["duplicates_prevented"], Value::from(0_u64));
        assert_eq!(fields["selection_reasons"], Value::Array(Vec::new()));
        assert_eq!(
            fields["planner_dimensions_scope"],
            Value::from("unavailable_at_runner_execution_boundary")
        );
        assert_eq!(fields["planner_dimensions_known"], Value::from(false));
        assert_eq!(fields["counts_capped"], Value::from(false));

        let bounded = plan_summary_telemetry_fields_from_counts(usize::MAX, usize::MAX);
        assert_eq!(
            bounded["logical_tasks"],
            Value::from(MAX_TELEMETRY_PLAN_ITEMS)
        );
        assert_eq!(
            bounded["physical_actions"],
            Value::from(MAX_TELEMETRY_PLAN_ITEMS)
        );
        assert_eq!(bounded["counts_capped"], Value::from(true));
    }

