    fn run_service_error_body(status: u16) -> String {
        serde_json::json!({
            "source": "actions-run-service",
            "statusCode": status,
            "errorMessage": "message",
        })
        .to_string()
    }

    struct AcquisitionDropGuard(Arc<AtomicBool>);

    impl Drop for AcquisitionDropGuard {
        fn drop(&mut self) {
            self.0.store(true, Ordering::SeqCst);
        }
    }

    #[tokio::test]
    async fn admission_signal_does_not_cancel_an_in_flight_acquire() {
        let dropped = Arc::new(AtomicBool::new(false));
        let acquire_dropped = Arc::clone(&dropped);
        let (started_tx, started_rx) = oneshot::channel();
        let (observe_started_tx, observe_started_rx) = oneshot::channel();
        let (signal_observed_tx, signal_observed_rx) = oneshot::channel();
        let (response_tx, response_rx) = oneshot::channel();
        let acquire = async move {
            let _drop_guard = AcquisitionDropGuard(acquire_dropped);
            let _ = started_tx.send(());
            let _ = observe_started_tx.send(());
            let _ = response_rx.await;
            "acquire response"
        };
        let admission_signal = async move {
            let _ = started_rx.await;
            let _ = signal_observed_tx.send(());
            CapacityBlockSignal::DiskPressure(DiskPressureAdmissionState::PressureActive)
        };
        let acquisition = tokio::spawn(async move {
            await_acquire_with_admission_signal(acquire, admission_signal).await
        });

        observe_started_rx.await.unwrap();
        signal_observed_rx.await.unwrap();
        tokio::task::yield_now().await;
        assert!(
            !dropped.load(Ordering::SeqCst),
            "pressure observation must not drop the unresolved acquire future"
        );
        response_tx.send(()).unwrap();

        let (result, signal) = acquisition.await.unwrap();
        assert_eq!(result, "acquire response");
        assert_eq!(
            signal,
            Some(CapacityBlockSignal::DiskPressure(
                DiskPressureAdmissionState::PressureActive
            ))
        );
        assert!(dropped.load(Ordering::SeqCst));
    }

    /// A conflict is not proof that this runner lost the job.
    ///
    /// Upstream's `RunServiceError` carries `source`, `statusCode` and
    /// `errorMessage` and no runner identity, so a 409 cannot distinguish "we
    /// acquired this and then crashed" from "another runner has it". Dropping
    /// the row on a 409 would throw away the only evidence that this runner may
    /// hold the lease; promoting on one would let two runners publish a
    /// terminal result. So it does neither: the row waits for `renewjob`.
    #[test]
    fn a_conflict_reply_neither_promotes_nor_drops_the_acquisition_intent() {
        let dir = unique_temp_dir("acquire-conflict-keeps-intent");
        fs::create_dir_all(&dir).unwrap();
        drop(ready_slot_journal(&dir));

        intend_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://broker.example/jobs/123",
        )
        .unwrap();

        let conflict = run_service_error_body(409);
        assert!(
            !acquire_reply_is_definitely_gone(&conflict),
            "a conflict is never a definite gone"
        );
        // The runner only abandons when the reply is definitely gone, so on a
        // conflict nothing is called and the row stays exactly as it was.
        let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
        let state = journal.materialized_state().unwrap();
        assert_eq!(state.jobs.len(), 1);
        assert!(
            state.jobs[0].provisional,
            "a conflict must not promote the row to ownership"
        );
        assert_eq!(
            state.jobs[0].job_id.0, "request-1",
            "the row is still keyed by the broker request"
        );
        assert_eq!(state.advertised_capacity(), 0, "the slot stays occupied");
        drop(journal);
        fs::remove_dir_all(&dir).ok();
    }

    /// Only a typed 404 proves that the broker request is gone and frees the
    /// slot immediately.
    #[test]
    fn typed_404_gone_reply_releases_the_acquisition_intent_and_slot() {
        let dir = unique_temp_dir("acquire-gone-404");
        fs::create_dir_all(&dir).unwrap();
        drop(ready_slot_journal(&dir));

        intend_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://run.example/run",
        )
        .unwrap();

        let body = run_service_error_body(404);
        assert!(acquire_reply_is_definitely_gone(&body));
        assert!(acquire_skip_abandons_intent(
            AcquireJobSkipReason::NotFound,
            BrokerErrorCategory::Terminal
        ));
        abandon_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://run.example/run",
            "the run service reports the broker message is gone",
        )
        .unwrap();

        let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
        let state = journal.materialized_state().unwrap();
        assert!(state.jobs.is_empty());
        assert_eq!(state.advertised_capacity(), 1);
        drop(journal);
        fs::remove_dir_all(&dir).ok();
    }

    /// 422 has a distinct typed disposition, but it does not prove that the
    /// request is gone. Keep the exact provisional row for renewal recovery.
    #[test]
    fn typed_422_unprocessable_reply_keeps_provisional_intent_and_capacity() {
        let dir = unique_temp_dir("acquire-unprocessable-422");
        fs::create_dir_all(&dir).unwrap();
        drop(ready_slot_journal(&dir));

        intend_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://run.example/run",
        )
        .unwrap();

        let body = run_service_error_body(422);
        assert!(!acquire_reply_is_definitely_gone(&body));
        assert!(!acquire_skip_abandons_intent(
            AcquireJobSkipReason::Unprocessable,
            BrokerErrorCategory::Conflict
        ));

        let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
        let state = journal.materialized_state().unwrap();
        assert_eq!(state.jobs.len(), 1);
        assert!(state.jobs[0].provisional);
        assert_eq!(state.jobs[0].job_id.0, "request-1");
        assert_eq!(state.jobs[0].plan_id, "");
        assert_eq!(state.advertised_capacity(), 0);
        drop(journal);
        fs::remove_dir_all(&dir).ok();
    }

    /// The abandon policy uses both typed reason and category, never parsing
    /// response text at this layer.
    #[test]
    fn acquire_skip_abandons_only_typed_not_found_terminal_pair() {
        assert!(acquire_skip_abandons_intent(
            AcquireJobSkipReason::NotFound,
            BrokerErrorCategory::Terminal
        ));
        assert!(!acquire_skip_abandons_intent(
            AcquireJobSkipReason::AlreadyAcquired,
            BrokerErrorCategory::Conflict
        ));
        assert!(!acquire_skip_abandons_intent(
            AcquireJobSkipReason::Unprocessable,
            BrokerErrorCategory::Conflict
        ));
        assert!(!acquire_skip_abandons_intent(
            AcquireJobSkipReason::NotFound,
            BrokerErrorCategory::Conflict
        ));
        assert!(!acquire_skip_abandons_intent(
            AcquireJobSkipReason::Unprocessable,
            BrokerErrorCategory::Transient
        ));
    }

    /// The acquire reply's identity replaces the broker request's, in one write,
    /// and the row only then becomes probeable.
    #[test]
    fn the_acquire_reply_retargets_the_intent_onto_the_run_service_job() {
        let dir = unique_temp_dir("acquire-retarget-identity");
        fs::create_dir_all(&dir).unwrap();
        drop(ready_slot_journal(&dir));

        intend_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://broker.example/jobs/123",
        )
        .unwrap();
        resolve_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://broker.example/jobs/123",
            "https://selected-run.example/jobs/456",
            &AcquiredJobIdentity {
                plan_id: "plan-1".to_owned(),
                job_id: "job-1".to_owned(),
            },
        )
        .unwrap();

        {
            let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
            let state = journal.materialized_state().unwrap();
            assert_eq!(state.jobs.len(), 1, "one row, retargeted, never two");
            assert_eq!(state.jobs[0].job_id.0, "job-1");
            assert_eq!(state.jobs[0].plan_id, "plan-1");
            assert_eq!(
                state.jobs[0].run_service_url,
                "https://selected-run.example/jobs/456"
            );
            assert!(state.jobs[0].provisional, "the reply is not yet ownership");
            assert_eq!(state.advertised_capacity(), 0);
        }

        // The durable marker then promotes that same row.
        accept_run_service_job_in_journal(&dir, &dir, "job-1").unwrap();
        let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
        let state = journal.materialized_state().unwrap();
        assert_eq!(state.jobs.len(), 1);
        assert!(!state.jobs[0].provisional);
        assert_eq!(state.jobs[0].plan_id, "plan-1");
        drop(journal);
        fs::remove_dir_all(&dir).ok();
    }

    /// The slot journal becoming usable only *after* the acquire reply is not a
    /// reason to give the job back.
    ///
    /// The intent is written before the acquire call precisely so a crash in
    /// that window leaves evidence. But the journal can come into being — or
    /// gain its slot rows — between the intent and the resolve, in which case
    /// the resolve finds no provisional row at all. Treating that as fatal used
    /// to end the V2 run loop, which dropped the broker session under a job
    /// GitHub still considered assigned, and GitHub failed it with "The
    /// self-hosted runner lost communication with the server". The 200 is the
    /// stronger evidence of the two: the row is rebuilt from the reply, and the
    /// job goes on to run and complete.
    #[test]
    fn a_missing_acquisition_intent_is_rebuilt_from_the_acquire_reply() {
        let dir = unique_temp_dir("acquire-rebuild-missing-intent");
        fs::create_dir_all(&dir).unwrap();
        drop(ready_slot_journal(&dir));
        // No `intend_run_service_acquisition_in_journal` call: the journal was
        // not usable yet, which is exactly the state the incident produced.

        let identity = AcquiredJobIdentity {
            plan_id: "plan-1".to_owned(),
            job_id: "job-1".to_owned(),
        };
        let rebuilt = resolve_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://broker.example/jobs/123",
            "https://selected-run.example/jobs/456",
            &identity,
        )
        .expect("a missing intent must be repaired, not end the run loop");
        assert!(rebuilt, "the caller is told a row was rebuilt");

        {
            let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
            let state = journal.materialized_state().unwrap();
            assert_eq!(state.jobs.len(), 1, "one rebuilt row, never a fork");
            assert_eq!(state.jobs[0].job_id.0, "job-1");
            assert_eq!(state.jobs[0].plan_id, "plan-1");
            assert_eq!(
                state.jobs[0].run_service_url, "https://selected-run.example/jobs/456",
                "the rebuilt row carries everything a renewjob probe needs"
            );
            assert!(
                state.jobs[0].provisional,
                "a 200 acquire reply retargets; only the durable marker owns"
            );
            assert_eq!(state.advertised_capacity(), 0, "the slot stays occupied");
        }

        // The rebuilt row has to be usable downstream, or the repair only moves
        // the crash one step further along.
        accept_run_service_job_in_journal(&dir, &dir, "job-1").unwrap();
        let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
        let state = journal.materialized_state().unwrap();
        assert_eq!(state.jobs.len(), 1);
        assert!(!state.jobs[0].provisional, "the job reaches ownership");
        drop(journal);
        fs::remove_dir_all(&dir).ok();
    }

    /// A journal that already holds the acquired identity is adopted, never
    /// forked: an owned row for `job-1` *is* the evidence the rebuild would
    /// write, and a second row for the same job would race the first one to the
    /// terminal send.
    #[test]
    fn rebuilding_an_intent_adopts_an_existing_row_instead_of_forking_one() {
        let dir = unique_temp_dir("acquire-rebuild-adopts-row");
        fs::create_dir_all(&dir).unwrap();
        drop(ready_slot_journal(&dir));
        // A previous attempt already carried this job to ownership.
        intend_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-0",
            "msg-0",
            "https://run.example/run",
        )
        .unwrap();
        resolve_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-0",
            "msg-0",
            "https://run.example/run",
            "https://selected-run.example/jobs/123",
            &AcquiredJobIdentity {
                plan_id: "plan-1".to_owned(),
                job_id: "job-1".to_owned(),
            },
        )
        .unwrap();
        accept_run_service_job_in_journal(&dir, &dir, "job-1").unwrap();

        let rebuilt = resolve_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://run.example/run",
            "https://selected-run.example/jobs/123",
            &AcquiredJobIdentity {
                plan_id: "plan-1".to_owned(),
                job_id: "job-1".to_owned(),
            },
        )
        .unwrap();

        assert!(!rebuilt, "nothing had to be written");
        let journal = velnor_control::journal::Journal::open(dir.join("journal.db")).unwrap();
        let state = journal.materialized_state().unwrap();
        assert_eq!(state.jobs.len(), 1);
        assert!(
            !state.jobs[0].provisional,
            "the existing ownership is left exactly as it was"
        );
        assert_eq!(state.advertised_capacity(), 0);
        drop(journal);
        fs::remove_dir_all(&dir).ok();
    }

    /// A configless runner has no journal to repair, and the resolve must stay
    /// the no-op it has always been there — including not conjuring a config
    /// directory into existence just because a broker message arrived.
    #[test]
    fn resolving_without_a_journal_stays_a_no_op() {
        let dir = unique_temp_dir("acquire-resolve-configless");
        let rebuilt = resolve_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://run.example/run",
            "https://selected-run.example/jobs/123",
            &AcquiredJobIdentity {
                plan_id: "plan-1".to_owned(),
                job_id: "job-1".to_owned(),
            },
        )
        .unwrap();
        assert!(!rebuilt);
        assert!(
            !dir.join("journal.db").exists(),
            "no journal may be created for a runner with no config directory"
        );
        fs::remove_dir_all(&dir).ok();
    }

    /// Repair is bounded by the journal, not by optimism. When the journal
    /// cannot be written at all the error stays fatal: carrying on without the
    /// durable step would recreate the lost-acquisition window this journal
    /// exists to close, and the job would be stranded until its lease expired.
    #[test]
    fn an_unwritable_journal_is_still_fatal_at_resolve() {
        let dir = unique_temp_dir("acquire-resolve-unwritable");
        fs::create_dir_all(&dir).unwrap();
        drop(ready_slot_journal(&dir));
        // A directory where the journal file belongs makes every write fail.
        fs::remove_file(dir.join("journal.db")).unwrap();
        fs::create_dir(dir.join("journal.db")).unwrap();

        let error = resolve_run_service_acquisition_in_journal(
            &dir,
            &dir,
            "request-1",
            "msg-1",
            "https://run.example/run",
            "https://selected-run.example/jobs/123",
            &AcquiredJobIdentity {
                plan_id: "plan-1".to_owned(),
                job_id: "job-1".to_owned(),
            },
        )
        .expect_err("a journal that cannot be written must not be skipped");

        assert!(
            !error.to_string().contains("no acquisition intent"),
            "the failure is the journal, not a missing row: {error}"
        );
        fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn acquired_job_identity_uses_ordered_wire_ids_and_normalized_model() {
        let lower = crate::job_message::WireAgentJobRequestMessage::from_value(serde_json::json!({
            "plan": { "planId": "BBBBBBBB-BBBB-BBBB-BBBB-BBBBBBBBBBBB" },
            "jobId": "AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA"
        }))
        .unwrap();
        let upper = crate::job_message::WireAgentJobRequestMessage::from_value(serde_json::json!({
            "pLaN": { "pLaNiD": "{CCCCCCCC-CCCC-CCCC-CCCC-CCCCCCCCCCCC}" },
            "jObId": "DDDDDDDD-DDDD-DDDD-DDDD-DDDDDDDDDDDD"
        }))
        .unwrap();
        let lower_identity = crate::protocol::AcquiredJobIdentity {
            plan_id: Some("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb".into()),
            job_id: Some("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa".into()),
        };
        let upper_identity = crate::protocol::AcquiredJobIdentity {
            plan_id: Some("cccccccc-cccc-cccc-cccc-cccccccccccc".into()),
            job_id: Some("dddddddd-dddd-dddd-dddd-dddddddddddd".into()),
        };

        assert_eq!(
            acquired_job_identity(&lower_identity, Some(&lower)),
            Some(AcquiredJobIdentity {
                plan_id: "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb".into(),
                job_id: "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa".into(),
            })
        );
        assert_eq!(
            acquired_job_identity(&upper_identity, Some(&upper)),
            Some(AcquiredJobIdentity {
                plan_id: "cccccccc-cccc-cccc-cccc-cccccccccccc".into(),
                job_id: "dddddddd-dddd-dddd-dddd-dddddddddddd".into(),
            })
        );
        assert_eq!(
            acquired_job_identity(&lower_identity, None),
            Some(AcquiredJobIdentity {
                plan_id: "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb".into(),
                job_id: "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa".into(),
            }),
            "explicit wire identity remains settleable when local DTO materialization failed"
        );
        assert_eq!(acquired_job_identity(&lower_identity, Some(&upper)), None);
    }

    #[test]
    fn acquired_job_identity_does_not_promote_absent_or_empty_guid_metadata() {
        let missing_job =
            crate::job_message::WireAgentJobRequestMessage::from_value(serde_json::json!({
                "plan": { "planId": "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb" }
            }))
            .unwrap();
        let missing_plan =
            crate::job_message::WireAgentJobRequestMessage::from_value(serde_json::json!({
                "jobId": "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"
            }))
            .unwrap();
        let null_job =
            crate::job_message::WireAgentJobRequestMessage::from_value(serde_json::json!({
                "plan": { "planId": "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb" },
                "jobId": null
            }))
            .unwrap();
        let zero_job =
            crate::job_message::WireAgentJobRequestMessage::from_value(serde_json::json!({
                "plan": { "planId": "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb" },
                "jobId": "00000000-0000-0000-0000-000000000000"
            }))
            .unwrap();
        let zero_plan =
            crate::job_message::WireAgentJobRequestMessage::from_value(serde_json::json!({
                "plan": { "planId": "00000000-0000-0000-0000-000000000000" },
                "jobId": "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"
            }))
            .unwrap();

        let missing_job_identity = crate::protocol::AcquiredJobIdentity {
            job_id: None,
            plan_id: Some("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb".into()),
        };
        let missing_plan_identity = crate::protocol::AcquiredJobIdentity {
            job_id: Some("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa".into()),
            plan_id: None,
        };
        let null_job_identity = missing_job_identity.clone();
        let zero_job_identity = crate::protocol::AcquiredJobIdentity {
            job_id: Some("00000000-0000-0000-0000-000000000000".into()),
            plan_id: Some("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb".into()),
        };
        let zero_plan_identity = crate::protocol::AcquiredJobIdentity {
            job_id: Some("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa".into()),
            plan_id: Some("00000000-0000-0000-0000-000000000000".into()),
        };

        for (identity, normalized) in [
            (missing_job_identity, missing_job),
            (missing_plan_identity, missing_plan),
            (null_job_identity, null_job),
            (zero_job_identity, zero_job),
            (zero_plan_identity, zero_plan),
        ] {
            assert_eq!(acquired_job_identity(&identity, Some(&normalized)), None);
        }
    }

