    fn partial_step_log(step_id: &str, lines: &[&str], completed_at: &str) -> StepLog {
        StepLog {
            step_id: step_id.to_string(),
            display_name: step_id.to_string(),
            order: 1,
            started_at: "2026-08-31T00:00:00.0000000Z".to_string(),
            completed_at: completed_at.to_string(),
            lines: lines.iter().map(|line| (*line).to_string()).collect(),
            masks: Vec::new(),
            annotations: Vec::new(),
            telemetry: Vec::new(),
            exit_code: 0,
            skipped: false,
            failure_ignored: false,
            error_count: 0,
            warning_count: 0,
            notice_count: 0,
            summary: String::new(),
        }
    }

    fn pages_job(job_id: &str, secret: &str) -> AgentJobRequestMessage {
        serde_json::from_value(serde_json::json!({
            "messageType": "PipelineAgentJobRequest",
            "plan": { "planId": "plan" },
            "timeline": { "id": "timeline" },
            "jobId": job_id,
            "jobDisplayName": "Check",
            "requestId": 1,
            "variables": {
                "system.github.token": { "value": secret, "isSecret": true },
                "github.repository": { "value": "endpoint-only-page-secret" }
            },
            "resources": {
                "endpoints": [{
                    "authorization": { "parameters": { "accessToken": "endpoint-only-page-secret" } }
                }]
            }
        }))
        .unwrap()
    }

    #[test]
    fn step_log_pages_are_written_by_the_sender_side_and_read_back_for_upload() {
        let root = unique_temp_dir("step-log-pages");
        let job = pages_job("hunter2", "ghs_jobsecret");
        let pages = Arc::new(StepLogPages::open(&root, &job));
        assert_eq!(pages.dir(), root.join("hunter2"));

        // The sink is attached to the real sender: a send persists the page
        // BEFORE the record reaches the channel, so the durable copy never
        // waits on the publisher.
        let (tx, mut rx) = tokio::sync::mpsc::channel(STEP_PUBLISH_CHANNEL_CAPACITY);
        let sender = BoundedStepSender::new(tx).with_sink(Arc::clone(&pages) as Arc<_>);

        // A live chunk registers its masks but writes no page.
        let mut live = partial_step_log("step-a", &["adding mask"], "");
        live.masks = vec!["hunter2".to_string()];
        sender.send_best_effort(live);
        assert!(fs::read_dir(pages.dir()).unwrap().next().is_none());

        // A skipped step writes no page either.
        let mut skipped = partial_step_log("step-skipped", &[], "2026-08-31T00:00:01.0000000Z");
        skipped.skipped = true;
        sender.send_best_effort(skipped);
        assert!(fs::read_dir(pages.dir()).unwrap().next().is_none());

        // The final record of a later step is masked with the job secret AND
        // the mask an earlier record registered, then written as blob lines.
        let mut done = partial_step_log(
            "step-hunter2",
            &[
                "token ghs_jobsecret pw hunter2",
                "Blocking waiting for file lock on build directory",
            ],
            "2026-08-31T00:00:02.0000000Z",
        );
        done.order = 7;
        done.exit_code = 3;
        done.display_name = "Run endpoint-only-page-secret hunter2".to_string();
        sender.send_best_effort(done.clone());
        let page = pages.dir().join("007-step-hunter2.log");
        let content = fs::read_to_string(&page).unwrap();
        assert!(!content.contains("ghs_jobsecret"), "{content}");
        assert!(!content.contains("hunter2"), "{content}");
        assert!(content.contains("token *** pw ***"), "{content}");
        assert!(
            content.contains("[velnor] waiting for Cargo build lock"),
            "{content}"
        );
        assert!(content.contains("job=*** repo=***"), "{content}");
        for line in content.lines() {
            // `YYYY-MM-DDTHH:MM:SS.fffffffZ ` is 28 chars plus the separator.
            assert!(
                line.len() > 28 && line.as_bytes()[27] == b'Z' && line.as_bytes()[28] == b' ',
                "blob line must carry the 7-digit timestamp prefix: {line:?}"
            );
        }
        // The upload reads exactly the page.
        assert_eq!(
            pages.read_page(&done).unwrap(),
            content.lines().map(str::to_owned).collect::<Vec<_>>()
        );
        let index = fs::read_to_string(pages.dir().join(STEP_LOG_PAGE_INDEX)).unwrap();
        assert!(!index.contains("endpoint-only-page-secret"), "{index}");
        assert_eq!(
            index.split('\t').nth(2).unwrap(),
            page.file_name().unwrap().to_str().unwrap(),
            "index filename must stay identical to the physical page name"
        );
        assert_eq!(
            index, "7\t3\t007-step-hunter2.log\tRun *** ***\n",
            "index masks display text but preserves the opaque page filename"
        );
        // Every record still reached the channel, in order.
        let mut received = Vec::new();
        while let Ok(log) = rx.try_recv() {
            received.push(log.step_id);
        }
        assert_eq!(received, vec!["step-a", "step-skipped", "step-hunter2"]);

        // The backstop persists only records without a page.
        let unseen = partial_step_log("step-c", &["late"], "2026-08-31T00:00:03.0000000Z");
        pages.persist_missing(&[done.clone(), unseen]);
        assert_eq!(fs::read_to_string(&page).unwrap(), content);
        assert!(pages.dir().join("001-step-c.log").is_file());
        assert!(pages
            .read_page(&partial_step_log("nope", &[], "x"))
            .is_err());
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn step_log_pages_retain_only_the_newest_jobs() {
        let root = unique_temp_dir("step-log-pages-retention");
        for index in 0..STEP_LOG_PAGE_JOBS_RETAINED + 3 {
            let job = pages_job(&format!("job-{index:03}"), "s");
            let pages = StepLogPages::open(&root, &job);
            fs::write(pages.dir().join("marker"), b"x").unwrap();
            let count = fs::read_dir(&root).unwrap().count();
            assert!(
                count <= STEP_LOG_PAGE_JOBS_RETAINED,
                "{count} job dirs after job {index}"
            );
            // Distinct mtimes so the prune order is the creation order.
            let stamp = UNIX_EPOCH + Duration::from_secs(1_700_000_000 + index as u64);
            fs::File::open(pages.dir())
                .unwrap()
                .set_modified(stamp)
                .unwrap();
        }
        assert!(!root.join("job-000").exists());
        assert!(!root.join("job-002").exists());
        assert!(root.join("job-003").exists());
        assert!(root
            .join(format!("job-{:03}", STEP_LOG_PAGE_JOBS_RETAINED + 2))
            .exists());
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn streamed_step_log_mirror_evicts_oldest_at_entry_cap() {
        let mut mirror = StreamedStepLogMirror::default();
        for index in 0..STREAMED_STEP_LOG_MIRROR_MAX_LOGS + 10 {
            mirror.push_owned(partial_step_log(&format!("step-{index}"), &["line"], ""));
        }
        assert_eq!(mirror.len(), STREAMED_STEP_LOG_MIRROR_MAX_LOGS);
        // Every eviction is counted for the forensics line and the
        // cancel-path truncation marker.
        assert_eq!(mirror.evicted(), 10);
        let logs = mirror.take_logs();
        assert_eq!(logs.len(), STREAMED_STEP_LOG_MIRROR_MAX_LOGS);
        // Oldest evicted first, arrival order preserved for the merge.
        assert_eq!(logs[0].step_id, "step-10");
        assert_eq!(
            logs[STREAMED_STEP_LOG_MIRROR_MAX_LOGS - 1].step_id,
            format!("step-{}", STREAMED_STEP_LOG_MIRROR_MAX_LOGS + 9)
        );
        assert_eq!(mirror.len(), 0);
        assert_eq!(mirror.bytes(), 0);
    }

    #[test]
    fn streamed_step_log_mirror_evicts_oldest_at_byte_cap() {
        let mut mirror = StreamedStepLogMirror::default();
        let big_line = "x".repeat(1024 * 1024);
        for index in 0..100 {
            let mut log = partial_step_log(&format!("step-{index}"), &[], "");
            log.lines = vec![big_line.clone()];
            mirror.push_owned(log);
        }
        assert!(mirror.bytes() <= STREAMED_STEP_LOG_MIRROR_MAX_BYTES);
        assert!(mirror.len() < 100);
        // Byte-cap evictions are counted too: pushed minus retained.
        assert_eq!(mirror.evicted(), 100 - mirror.len() as u64);
        // The most recent window survives the byte cap.
        let logs = mirror.take_logs();
        assert_eq!(logs[logs.len() - 1].step_id, "step-99");
    }

    #[test]
    fn streamed_step_log_mirror_keeps_single_oversize_record() {
        let mut mirror = StreamedStepLogMirror::default();
        let mut log = partial_step_log("huge", &[], "");
        log.lines = vec!["x".repeat(STREAMED_STEP_LOG_MIRROR_MAX_BYTES as usize + 1)];
        mirror.push_owned(log);
        // One record is retained alone: the same record is inherently
        // retained in `ScriptJobResult`, so keeping one copy in the mirror
        // adds no new wedge vector — while dropping it would lose the
        // cancel-path log without bounding anything further.
        assert_eq!(mirror.len(), 1);
        assert_eq!(mirror.take_logs()[0].step_id, "huge");
    }

    #[test]
    fn streamed_step_log_mirror_shares_records_without_cloning_payload() {
        // The publisher hands the mirror an Arc bump per chunk — never a
        // full StepLog clone — with the byte size measured before locking.
        let mut mirror = StreamedStepLogMirror::default();
        let log = Arc::new(partial_step_log("step-1", &["a", "b"], ""));
        let bytes = step_log_mirror_bytes(&log);
        mirror.push(Arc::clone(&log), bytes);
        // Exactly two owners: this handle (the publisher side) plus the
        // mirror. A clone-per-chunk mirror would hold a second payload
        // instead of sharing this one.
        assert_eq!(Arc::strong_count(&log), 2);
        assert_eq!(mirror.bytes(), bytes);
        drop(log);
        // Last owner is the mirror, so take moves the record out.
        let logs = mirror.take_logs();
        assert_eq!(logs.len(), 1);
        assert_eq!(logs[0].step_id, "step-1");
        assert_eq!(logs[0].lines, vec!["a".to_string(), "b".to_string()]);
        assert_eq!(mirror.len(), 0);
        assert_eq!(mirror.bytes(), 0);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn step_log_publisher_contended_push_pends_without_parking_the_executor() {
        // Production-coupled contention probe: the push under test runs
        // inside the real `start_step_log_publisher` task (not a
        // hand-rolled lock/unlock), and the mirror is passed to it by
        // value — reverting production to `std::sync::Mutex` breaks
        // compilation here, so the async-mutex wiring cannot silently
        // regress. While the production-typed lock is held, the
        // publisher's per-chunk push must pend WITHOUT blocking the
        // thread: on this current-thread runtime a blocking mutex would
        // wedge the only thread and the timeout below could never fire.
        // The job carries no endpoints, so the publisher performs no feed
        // or results I/O; the live chunk below also skips the Twirp and
        // timeline completion uploads.
        let job: AgentJobRequestMessage = serde_json::from_value(serde_json::json!({
            "messageType": "PipelineAgentJobRequest",
            "plan": { "planId": "plan" },
            "timeline": { "id": "timeline" },
            "jobId": "job",
            "jobDisplayName": "Check",
            "requestId": 1,
        }))
        .unwrap();
        let mirror = Arc::new(tokio::sync::Mutex::new(StreamedStepLogMirror::default()));
        let (sender, receiver) = tokio::sync::mpsc::channel(STEP_PUBLISH_CHANNEL_CAPACITY);
        let held = mirror.lock().await;
        let pages_root = unique_temp_dir("step-log-publisher-contended");
        let pages = Arc::new(StepLogPages::open(&pages_root, &job));
        let mut publisher = start_step_log_publisher(
            job,
            receiver,
            StepPublishSpill::new(),
            None,
            Arc::clone(&mirror),
            pages,
        );
        sender
            .send(partial_step_log("contended", &["line"], ""))
            .await
            .unwrap();
        // Executor still makes progress while the publisher waits on the
        // contended lock: the timer fires instead of parking behind a
        // blocked worker.
        assert!(
            tokio::time::timeout(Duration::from_millis(100), &mut publisher)
                .await
                .is_err(),
            "publisher push must pend while the mirror lock is held"
        );
        drop(held);
        drop(sender);
        tokio::time::timeout(Duration::from_secs(5), publisher)
            .await
            .expect("publisher must drain after unlock")
            .unwrap();
        assert_eq!(mirror.lock().await.len(), 1);
    }

    #[tokio::test]
    async fn publish_with_timeout_for_bounds_stalled_publish() {
        let err = publish_with_timeout_for::<()>(
            Duration::from_millis(10),
            std::future::pending::<Result<()>>(),
        )
        .await
        .unwrap_err()
        .to_string();
        assert!(err.contains("timed out"), "{err}");
        // Fast and failed publishes pass through unchanged.
        assert_eq!(
            publish_with_timeout_for(Duration::from_secs(5), async { Ok::<_, anyhow::Error>(7) })
                .await
                .unwrap(),
            7
        );
        let inner = publish_with_timeout_for(Duration::from_secs(5), async {
            Err::<(), _>(anyhow::anyhow!("backend exploded"))
        })
        .await
        .unwrap_err()
        .to_string();
        assert!(inner.contains("backend exploded"), "{inner}");
    }

    #[tokio::test]
    async fn drain_step_publishers_waits_for_both_publishers_before_exit() {
        let timeline_done = Arc::new(AtomicBool::new(false));
        let logs_done = Arc::new(AtomicBool::new(false));
        let timeline_flag = Arc::clone(&timeline_done);
        let logs_flag = Arc::clone(&logs_done);
        let timeline = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(50)).await;
            timeline_flag.store(true, Ordering::SeqCst);
        });
        let logs_publisher = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(50)).await;
            logs_flag.store(true, Ordering::SeqCst);
        });
        let log_dir = std::env::temp_dir().join(format!(
            "r1pub-drain-test-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|elapsed| elapsed.as_nanos())
                .unwrap_or(0)
        ));
        let forensics = SlotForensics::new(log_dir.clone(), "r1pub-drain-test".to_string());
        let start_drops = AtomicU64::new(4);
        let log_drops = AtomicU64::new(9);
        let mirror = Arc::new(tokio::sync::Mutex::new(StreamedStepLogMirror::default()));
        for index in 0..STREAMED_STEP_LOG_MIRROR_MAX_LOGS + 7 {
            mirror.lock().await.push_owned(partial_step_log(
                &format!("step-{index}"),
                &["line"],
                "",
            ));
        }
        drain_step_publishers(
            timeline,
            logs_publisher,
            forensics,
            &start_drops,
            &log_drops,
            &mirror,
        )
        .await;
        // Drain-before-exit: terminal completion is ordered after both
        // publishers finish, so both flags are set when drain returns.
        assert!(timeline_done.load(Ordering::SeqCst));
        assert!(logs_done.load(Ordering::SeqCst));
        // The forensics line carries all three loss counts, including the
        // mirror evictions the cancel path needs to account for.
        let lifecycle = std::fs::read_to_string(log_dir.join(crate::slot_log::LIFECYCLE_LOG))
            .expect("drain must append the forensics line");
        assert!(lifecycle.contains("step-publishers-drained"), "{lifecycle}");
        assert!(lifecycle.contains("dropped_step_starts=4"), "{lifecycle}");
        assert!(lifecycle.contains("dropped_step_logs=9"), "{lifecycle}");
        assert!(lifecycle.contains("mirror_evicted_logs=7"), "{lifecycle}");
        let _ = std::fs::remove_dir_all(&log_dir);
    }

    #[tokio::test]
    async fn drain_step_publisher_aborts_a_stalled_publisher() {
        let stalled = tokio::spawn(std::future::pending::<()>());
        let started = Instant::now();
        drain_step_publisher("test", stalled, Duration::from_millis(10)).await;
        assert!(
            started.elapsed() < Duration::from_secs(5),
            "drain did not abort the stalled publisher: {:?}",
            started.elapsed()
        );
    }

    #[test]
    fn bounded_step_publish_soak_proves_memory_ceiling() {
        // Soak: a chatty job (100k live log lines) against a stalled
        // publisher (no receiver progress). The bounded channel must absorb
        // the burst as counted drops and the mirror must hold the ceiling —
        // neither may grow with the number of emitted events.
        let (tx, mut rx) = tokio::sync::mpsc::channel(STEP_PUBLISH_CHANNEL_CAPACITY);
        let spill = StepPublishSpill::new();
        let sender = BoundedStepSender::with_spill(tx, Arc::clone(&spill));
        let mirror = Arc::new(tokio::sync::Mutex::new(StreamedStepLogMirror::default()));
        let started = Instant::now();
        let events: u64 = 100_000;
        for index in 0..events {
            let mut log = partial_step_log("soak", &[], "");
            log.lines = vec![format!("soak line {index}")];
            sender.send_best_effort(log.clone());
            // Same push the log publisher performs per streamed record.
            // Sync test, uncontended: `blocking_lock` outside a runtime.
            let log = Arc::new(log);
            let size = step_log_mirror_bytes(&log);
            mirror.blocking_lock().push(Arc::clone(&log), size);
        }
        let elapsed = started.elapsed();
        let mirror_guard = mirror.blocking_lock();
        eprintln!(
            "step-publish soak: {events} events in {elapsed:?}, drops={}, mirror_len={}, mirror_bytes={}",
            sender.drops(),
            mirror_guard.len(),
            mirror_guard.bytes(),
        );
        let retained = STEP_PUBLISH_CHANNEL_CAPACITY as u64 + STEP_PUBLISH_OVERFLOW_CAPACITY as u64;
        assert_eq!(sender.drops(), events - retained);
        assert!(mirror_guard.len() <= STREAMED_STEP_LOG_MIRROR_MAX_LOGS);
        assert!(mirror_guard.bytes() <= STREAMED_STEP_LOG_MIRROR_MAX_BYTES);
        // The soak's overflow is fully accounted: every record past the
        // entry cap was counted as an oldest-first eviction.
        assert_eq!(
            mirror_guard.evicted(),
            events - STREAMED_STEP_LOG_MIRROR_MAX_LOGS as u64
        );
        drop(mirror_guard);
        // The sender never blocked: 100k events must stream in bounded time.
        assert!(
            elapsed < Duration::from_secs(60),
            "soak sender blocked: {elapsed:?}"
        );
        // The stalled publisher still drains the live channel plus the
        // ordered overflow once it makes progress — nothing was lost except
        // the counted drops past both buffers.
        let mut drained = 0u64;
        while rx.try_recv().is_ok() {
            drained += 1;
        }
        drained += spill.take_all().len() as u64;
        assert_eq!(drained, retained);
    }

    #[test]
    fn merged_partial_step_logs_fold_chunks_and_stamp_unfinished_steps() {
        let streamed = vec![
            partial_step_log("build", &["compiling a"], ""),
            partial_step_log("build", &["compiling b"], ""),
            partial_step_log("checkout", &["cloned"], "2026-08-31T00:00:01.0000000Z"),
            // A late live chunk for a step whose final snapshot already
            // landed must not duplicate its lines.
            partial_step_log("checkout", &["cloned"], ""),
        ];
        let merged = merged_partial_step_logs(streamed, 0, 0);
        assert_eq!(merged.len(), 2);
        assert_eq!(merged[0].step_id, "build");
        assert_eq!(merged[0].lines, vec!["compiling a", "compiling b"]);
        assert!(
            !merged[0].completed_at.is_empty(),
            "unfinished step must be stamped at cancellation"
        );
        assert_eq!(merged[1].step_id, "checkout");
        assert_eq!(merged[1].lines, vec!["cloned"]);
        assert_eq!(merged[1].completed_at, "2026-08-31T00:00:01.0000000Z");
    }

    #[test]
    fn merged_partial_step_logs_stamps_truncation_marker_when_records_lost() {
        let streamed = vec![partial_step_log("build", &["compiling"], "")];
        // No loss: no marker, output unchanged.
        let merged = merged_partial_step_logs(streamed.clone(), 0, 0);
        assert_eq!(merged[0].lines, vec!["compiling"]);
        // Channel drops alone stamp the marker with both counts.
        let merged = merged_partial_step_logs(streamed.clone(), 12, 0);
        assert_eq!(merged.len(), 1);
        assert!(
            merged[0].lines[0].contains("12 streamed step-log record(s) dropped"),
            "{}",
            merged[0].lines[0]
        );
        assert!(
            merged[0].lines[0].contains("0 evicted"),
            "{}",
            merged[0].lines[0]
        );
        assert_eq!(merged[0].lines[1], "compiling");
        // Mirror evictions alone stamp it too.
        let merged = merged_partial_step_logs(streamed, 0, 4096);
        assert!(
            merged[0].lines[0].contains("4096 evicted"),
            "{}",
            merged[0].lines[0]
        );
    }

    #[test]
    fn merged_partial_step_logs_synthesizes_notice_when_everything_lost() {
        // Nothing survived, but records were lost: the merge must not
        // complete with zero steps hiding the gap.
        let merged = merged_partial_step_logs(Vec::new(), 3, 5);
        assert_eq!(merged.len(), 1);
        assert_eq!(merged[0].step_id, "velnor-cancel-log-truncation");
        assert!(!merged[0].skipped);
        assert!(!merged[0].completed_at.is_empty());
        assert!(
            merged[0].lines[0].contains("3 streamed step-log record(s) dropped"),
            "{}",
            merged[0].lines[0]
        );
        assert!(
            merged[0].lines[0].contains("5 evicted"),
            "{}",
            merged[0].lines[0]
        );
        // Nothing lost and nothing streamed: still empty, no noise.
        let merged = merged_partial_step_logs(Vec::new(), 0, 0);
        assert!(merged.is_empty());
    }

    #[test]
    fn merged_partial_step_logs_marker_skips_unrendered_steps() {
        let mut skipped = partial_step_log("skipped-step", &["hidden"], "");
        skipped.skipped = true;
        let streamed = vec![skipped, partial_step_log("build", &["compiling"], "")];
        let merged = merged_partial_step_logs(streamed, 1, 0);
        // The marker must land where the combined job log renders it:
        // skipped steps are omitted there.
        assert_eq!(merged[0].lines, vec!["hidden"]);
        assert!(
            merged[1].lines[0].contains("truncated"),
            "{}",
            merged[1].lines[0]
        );
    }

    #[cfg(feature = "test-support")]
